/* =========================================================================
   TITAN ACADEMY — single-file prototype
   Sections:  ENGINE/STATE → CURRICULUM DATA → COMPONENTS → SCREENS
              → ROUTER → PROGRESS LOGIC → LOGIN
   ========================================================================= */

/* ---------- tiny helpers ---------- */
function $(id){return document.getElementById(id);}
function esc(s){return String(s==null?"":s).replace(/[&<>"']/g,function(c){return{"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c];});}
function toast(emoji,msg){var t=$("toast");t.querySelector(".te").textContent=emoji;t.querySelector(".tt").textContent=msg;t.classList.add("show");clearTimeout(t._t);t._t=setTimeout(function(){t.classList.remove("show");},2600);}

/* =========================================================================
   CURRICULUM DATA
   Each PATH = { id, name, who, days, summary, color, modules:[...] }
   Each MODULE = { id, title, objective, est, lessons:[...], quiz:{...}, sim?:{...} }
   Each LESSON = { id, title, type:'screen'|'article'|'video', est, body(html) }
   Each QUIZ = { questions:[ {q, opts:[...], correct:idx, why} ] }
   ========================================================================= */
function initialsOf(name){ var w=String(name||"").replace(/[^A-Za-z ]/g," ").trim().split(/\s+/).filter(Boolean); if(w.length>=2) return (w[0][0]+w[1][0]).toUpperCase(); return (w[0]||"TA").slice(0,2).toUpperCase(); }
function overallPct(){ var ids=(typeof accessibleIds==="function")?accessibleIds():[]; if(!ids.length) return 0; var done=0,tot=0; ids.forEach(function(id){ var p=getPath(id); if(!p) return; tot+=p.modules.length; done+=p.modules.filter(function(m){return moduleComplete(p,m);}).length; }); return tot?Math.round(done/tot*100):0; }
function animateHome(){
  try{
    document.querySelectorAll(".countup").forEach(function(el){ var to=+el.getAttribute("data-to")||0; if(to<=0){ el.textContent="0"; return; } var dur=900,st=null; function step(t){ if(st===null)st=t; var pr=Math.min((t-st)/dur,1); el.textContent=Math.round(to*pr); if(pr<1) requestAnimationFrame(step); } requestAnimationFrame(step); });
    requestAnimationFrame(function(){ document.querySelectorAll(".rbar i[data-pct]").forEach(function(b){ b.style.width=(+b.getAttribute("data-pct"))+"%"; }); });
  }catch(e){}
}
function celebrate(){
  try{ var c=document.createElement("div"); c.className="confetti"; var cols=["#0265DC","#6DBAF8","#3FB37F","#B68B4C","#ffffff"]; for(var i=0;i<34;i++){ var s=document.createElement("i"); s.style.left="50%"; s.style.top="40%"; s.style.background=cols[i%cols.length]; s.style.setProperty("--x",((Math.random()*2-1)*200)+"px"); s.style.setProperty("--y",(-(Math.random()*240+60))+"px"); s.style.setProperty("--r",(Math.random()*540-270)+"deg"); s.style.animationDelay=(Math.random()*0.1)+"s"; c.appendChild(s); } document.body.appendChild(c); setTimeout(function(){ c.remove(); },1500); if(navigator.vibrate) navigator.vibrate(30); }catch(e){}
}
function showUnlock(title){
  try{ var b=document.getElementById("unlockbar"); if(!b){ b=document.createElement("div"); b.id="unlockbar"; b.className="unlockbar"; document.body.appendChild(b); } b.innerHTML='<span class="uk">✓</span><span><b>'+esc(title)+'</b> complete · next module unlocked</span>'; b.classList.add("show"); clearTimeout(b._t); b._t=setTimeout(function(){ b.classList.remove("show"); },3400); }catch(e){}
}
function L(id,title,type,est,body,audio){return{id:id,title:title,type:type,est:est,body:body,audio:audio};}
function Q(q,opts,correct,why){return{q:q,opts:opts,correct:correct,why:why};}
