/* =========================================================================
   STATE & PERSISTENCE  (localStorage)
   ========================================================================= */
var STORE_KEY = "titan_academy_v1";
var DEFAULT_STATE = { progress:{}, quizzes:{}, sims:{}, xp:0, badges:[], refOpened:[], lastDay:null, streak:0, certs:{} };
var state = { view:"home", pathId:null, moduleId:null, lessonIdx:0, lessonMode:"read", simStep:0, simScore:0, quizIdx:0, quizAnswers:[], refFilter:"all", refQuery:"" };
var data = loadStore();

function loadStore(){ try{ var v=JSON.parse(localStorage.getItem(STORE_KEY)); return Object.assign({},DEFAULT_STATE,v||{}); }catch(e){ return Object.assign({},DEFAULT_STATE); } }
var TP_UID=null, _cloudTimer=null;
function saveStore(){ try{ localStorage.setItem(STORE_KEY,JSON.stringify(data)); }catch(e){} cloudSaveDebounced(); }
function cloudSaveDebounced(){ if(!sb||!TP_UID) return; clearTimeout(_cloudTimer); _cloudTimer=setTimeout(cloudSaveNow,1500); }
function cloudSaveNow(){ if(!sb||!TP_UID) return; try{ sb.from("titan_progress").upsert({user_id:TP_UID, progress:data, updated_at:new Date().toISOString()},{onConflict:"user_id"}).then(function(){},function(){}); }catch(e){} }

/* streak handling */
function touchStreak(){
  var today=new Date().toISOString().slice(0,10);
  if(data.lastDay===today) return;
  var yest=new Date(Date.now()-864e5).toISOString().slice(0,10);
  data.streak = (data.lastDay===yest) ? (data.streak||0)+1 : 1;
  data.lastDay=today;
  if(data.streak>=3) award("streak3");
  saveStore();
}

/* lookups */
var ADVANCED_PATHS={stacct:1,streports:1,stpricebook:1};
function getPath(id){ return CURRICULUM.find(function(p){return p.id===id;}); }
function getModule(p,id){ return p.modules.find(function(m){return m.id===id;}); }

/* progress keys */
function lessonDone(pid,mid,lid){ return !!(data.progress[pid+"."+mid+"."+lid]); }
function markLesson(pid,mid,lid){ var k=pid+"."+mid+"."+lid; if(!data.progress[k]){ data.progress[k]=1; award("first_lesson"); addXp(20,"Lesson complete"); } touchStreak(); checkModuleComplete(pid,mid); saveStore(); }
function quizPassed(pid,mid){ var r=data.quizzes[pid+"."+mid]; return r&&r.passed; }
function quizBest(pid,mid){ var r=data.quizzes[pid+"."+mid]; return r?r.score:null; }
function simPassed(pid,mid){ return !!data.sims[pid+"."+mid]; }

function moduleComplete(p,m){
  var lessonsDone = m.lessons.every(function(l){return lessonDone(p.id,m.id,l.id);});
  var qz = quizPassed(p.id,m.id);
  var sm = m.sim ? simPassed(p.id,m.id) : true;
  return lessonsDone && qz && sm;
}
function moduleUnlocked(p,idx){
  if(isOwner()) return true;
  if(idx===0) return true;
  return moduleComplete(p,p.modules[idx-1]);
}
function moduleProgressPct(p,m){
  var total = m.lessons.length + 1 + (m.sim?1:0);
  var done = m.lessons.filter(function(l){return lessonDone(p.id,m.id,l.id);}).length + (quizPassed(p.id,m.id)?1:0) + (m.sim&&simPassed(p.id,m.id)?1:0);
  return Math.round(done/total*100);
}
function pathProgressPct(p){
  var t=0,d=0;
  p.modules.forEach(function(m){ t+=m.lessons.length+1+(m.sim?1:0); d+=m.lessons.filter(function(l){return lessonDone(p.id,m.id,l.id);}).length+(quizPassed(p.id,m.id)?1:0)+(m.sim&&simPassed(p.id,m.id)?1:0); });
  return t?Math.round(d/t*100):0;
}
function pathCertified(p){ return p.modules.every(function(m){return moduleComplete(p,m);}); }

function checkModuleComplete(pid,mid){
  var p=getPath(pid),m=getModule(p,mid);
  if(moduleComplete(p,m)){
    var key="mod."+pid+"."+mid;
    if(!data.progress[key]){ data.progress[key]=1; award("first_module"); addXp(60,"Module complete"); celebrate(); showUnlock(m.title); }
    checkPathCert(p);
  }
}
function checkPathCert(p){
  if(pathCertified(p) && !data.certs[p.id]){
    data.certs[p.id]=new Date().toISOString().slice(0,10);
    award("first_cert"); addXp(200,"Certification");
    if(CURRICULUM.every(function(pp){return data.certs[pp.id];})) award("all_certs");
    saveStore();
    toast("🏆","Certified: "+p.name+"!");
  }
}

/* xp + badges */
function addXp(n,reason){ data.xp=(data.xp||0)+n; saveStore(); }
function levelFromXp(xp){ return Math.floor((xp||0)/300)+1; }
function award(id){ if(data.badges.indexOf(id)<0){ data.badges.push(id); saveStore(); var b=BADGES.find(function(x){return x.id===id;}); if(b) setTimeout(function(){toast(b.emoji,"Badge earned: "+b.name);},400); } }

/* =========================================================================
   COMPONENTS
   ========================================================================= */
function ring(pct,size,stroke,color){
  size=size||48; stroke=stroke||5; color=color||"var(--gold)";
  var r=(size-stroke)/2, c=2*Math.PI*r, off=c*(1-pct/100);
  return '<svg width="'+size+'" height="'+size+'" viewBox="0 0 '+size+' '+size+'">'
    +'<circle cx="'+size/2+'" cy="'+size/2+'" r="'+r+'" fill="none" stroke="var(--line)" stroke-width="'+stroke+'"/>'
    +'<circle cx="'+size/2+'" cy="'+size/2+'" r="'+r+'" fill="none" stroke="'+color+'" stroke-width="'+stroke+'" stroke-linecap="round" stroke-dasharray="'+c.toFixed(1)+'" stroke-dashoffset="'+off.toFixed(1)+'"/></svg>';
}
function buildMenu(){
  var acct=currentAccount(); var who=acct?acct.name:"User"; var ov=overallPct();
  var map={home:"home",mypath:"mypath",path:"mypath",module:"mypath",lesson:"mypath",quiz:"mypath",quizresult:"mypath",sim:"mypath",simresult:"mypath",reference:"reference",refarticle:"reference",profile:"profile",admin:"admin",users:"users"};
  var active=map[state.view]||"home";
  var items=[["home","\u2302","Home"],["mypath","\u25C9","My Path"],["reference","\uD83D\uDD0D","Library"],["profile","\u2605","Profile"]];
  if(acct && acct.access==="all") items.push(["users","\uD83D\uDC65","Users"]);
  var theme=(document.body.getAttribute("data-theme")==="light")?"Dark mode":"Light mode";
  return '<div class="menupanel" onclick="event.stopPropagation()">'
    + '<div class="menuhd"><div class="mbrand">TITAN<b> ACADEMY</b></div><div class="muser">'+esc(who)+'</div><div class="mpct">'+ov+'% complete</div></div>'
    + '<div class="menunav">'
      + items.map(function(it){ return '<button class="'+(active===it[0]?"on":"")+'" onclick="menuGo(\''+it[0]+'\')"><span class="mi">'+it[1]+'</span>'+it[2]+'</button>'; }).join("")
    + '</div>'
    + '<div style="padding:8px 22px 6px;margin-top:4px;border-top:1px solid var(--line);font-size:9px;letter-spacing:1.6px;color:var(--muted-2);font-weight:700;text-transform:uppercase">Advanced</div>'
    + '<div class="menunav" style="padding-top:6px">'
      + '<button class="'+((state.view!=="home"&&state.pathId==="stacct")?"on":"")+'" onclick="openAdvAccounting()"><span class="mi">💰</span>Accounting</button>'
      + '<button class="'+((state.view!=="home"&&state.pathId==="streports")?"on":"")+'" onclick="openAdvReports()"><span class="mi">📈</span>Reports</button>'
      + '<button class="'+((state.view!=="home"&&state.pathId==="stpricebook")?"on":"")+'" onclick="openAdvPricebook()"><span class="mi">📕</span>Price Book</button>'
    + '</div>'
    + '<div class="menufoot">'
      + '<button onclick="toggleTheme();openMenu()"><span class="mi">\u25D0</span>'+theme+'</button>'
      + '<button onclick="logout()"><span class="mi">\u23FB</span>Sign out</button>'
    + '</div></div>';
}
function mountMenu(){
  var el=document.getElementById("menuoverlay");
  if(!el){ el=document.createElement("div"); el.id="menuoverlay"; el.className="menuoverlay"; el.onclick=closeMenu; document.body.appendChild(el); }
  return el;
}
function openMenu(){ var el=mountMenu(); el.innerHTML=buildMenu(); el.classList.add("show"); }
function closeMenu(){ var el=document.getElementById("menuoverlay"); if(el) el.classList.remove("show"); }
function menuGo(v){ closeMenu(); navTo(v); }
function openAdvAccounting(){ closeMenu(); openPath("stacct"); }
function openAdvReports(){ closeMenu(); openPath("streports"); }
function openAdvPricebook(){ closeMenu(); openPath("stpricebook"); }
function header(){
  return '<div class="topbar">'
    +'<button class="iconbtn menubtn" onclick="openMenu()" aria-label="Menu" title="Menu">\u2630</button>'
    +'<div class="ttl" onclick="navTo(\'home\')" title="Home">TITAN<b> ACADEMY</b></div>'
    +'<span class="topspacer"></span>'
    +'</div>';
}
function bnav(){ return ""; }
function crumbBar(parts){
  var html='<div class="crumbrow"><button class="back" onclick="goBack()">‹</button><div class="crumb">';
  parts.forEach(function(p,i){
    if(i>0) html+='<span class="sep">›</span>';
    html+='<span class="'+(i===parts.length-1?"cur":"seg")+'">'+esc(p)+'</span>';
  });
  return html+'</div></div>';
}

/* =========================================================================
   SCREENS
   ========================================================================= */
function homeScreen(){
  var lvl=levelFromXp(data.xp), xpInLvl=(data.xp||0)%300;
  var certCount=Object.keys(data.certs).length;
  var acct=currentAccount();
  var QUOTES=["Success is scheduled.","Master the process.","Every expert was once a beginner.","Train today. Lead tomorrow.","Knowledge creates confidence."];
  var quote=QUOTES[Math.floor(Math.random()*QUOTES.length)];
  var streak=data.streak||0;
  var cards=CURRICULUM.filter(function(p){return !ADVANCED_PATHS[p.id];}).map(function(p,ci){
    var allowed=canAccess(p.id);
    var cert=pathCertified(p);
    var m=p.modules;
    var doneM=m.filter(function(mm){return moduleComplete(p,mm);}).length;
    var pct=Math.round(doneM/m.length*100);
    var statusTxt, statusCls;
    if(!allowed){ statusTxt="Locked"; statusCls=""; }
    else if(doneM===m.length){ statusTxt="Completed"; statusCls="done"; }
    else if(doneM>0){ statusTxt="In progress"; statusCls="prog"; }
    else { statusTxt="Not started"; statusCls=""; }
    var isHome = allowed && acct && acct.home===p.id;
    var click = allowed ? 'onclick="openPath(\''+p.id+'\')"' : 'onclick="lockedTile()" title="Locked for your role"';
    return '<div class="rolecard'+(allowed?'':' locked')+(isHome?' current':'')+'" style="animation-delay:'+(ci*55)+'ms" '+click+'>'
      + (allowed?'':'<div class="lockbadge">🔒</div>')
      + '<div class="rname">'+esc(p.name)+'</div>'
      + '<div class="rmodlabel">Modules</div>'
      + '<div class="rmodrow"><span class="rcount">'+doneM+' / '+m.length+'</span><span class="rpct'+(allowed&&pct>0?' on':'')+'">'+(allowed?pct:0)+'%</span></div>'
      + '<div class="rbar"><i data-pct="'+(allowed?pct:0)+'" style="width:0%"></i></div>'
      + '<div class="rstatus '+statusCls+'"><span class="dot"></span>'+statusTxt+'</div>'
      + '</div>';
  }).join("");
  return header()+'<div class="home-anim">'
    + '<div class="hometag">Know the system. Own the outcome.</div>'
    + '<div class="grid">'+cards+'</div>'
    + '<div class="home-foot">Role-gated · linear unlock · pass-to-progress (80%)<br>Your reference library stays open forever once unlocked.</div>'
    + '</div>'+bnav();
}

function pathScreen(){
  var p=getPath(state.pathId);
  var pct=pathProgressPct(p), cert=pathCertified(p);
  var color = p.color==="gold" ? "var(--gold)" : "var(--cyan-2)";
  var doneM=p.modules.filter(function(mm){return moduleComplete(p,mm);}).length;
  var hero='<div class="pathhero"><div class="ring">'+ring(pct,78,7,color)+'<div class="num" style="color:'+color+'">'+pct+'%</div></div>'
    +'<div class="meta"><div class="nm">'+esc(p.name)+'</div><div class="dt">'+esc(p.summary)+'</div>'
    +'<div class="chips"><span class="chip '+(cert?'gold':'cyan')+'">'+doneM+'/'+p.modules.length+' modules</span>'
    +(cert?'<span class="chip gold">✓ Certified</span>':'<span class="chip muted">'+p.days+'-day path</span>')+'</div></div></div>';

  var steps='<div class="stepper">';
  p.modules.forEach(function(m,i){
    var unlocked=moduleUnlocked(p,i), complete=moduleComplete(p,m), current=unlocked&&!complete;
    var mpct=moduleProgressPct(p,m);
    var node=complete?'<div class="node done">✓</div>':current?'<div class="node current">'+(i+1)+'</div>':'<div class="node">'+(i+1)+'</div>';
    var stepsTotal=m.lessons.length+1+(m.sim?1:0);
    var stepsDone=m.lessons.filter(function(l){return lessonDone(p.id,m.id,l.id);}).length+(quizPassed(p.id,m.id)?1:0)+(m.sim&&simPassed(p.id,m.id)?1:0);
    var statusLabel=complete?'Complete':current?(mpct>0?'In progress':'Ready to start'):'Locked';
    var card='<div class="modcard'+(unlocked?'':' locked')+'" onclick="'+(unlocked?'openModule(\''+m.id+'\')':'lockMsg('+i+')')+'">'
      +'<div class="mt">'+esc(m.title)+(unlocked?'':'<span class="lk">🔒</span>')+'</div>'
      +'<div class="mo">'+esc(m.objective)+'</div>'
      +'<div class="modprog"><div class="pbar"><i class="'+(complete?'full':'')+'" style="width:'+mpct+'%"></i></div>'
      +'<div class="pmeta"><span class="pc'+(complete?' full':'')+'">'+mpct+'% · '+statusLabel+'</span>'
      +'<span>'+stepsDone+' / '+stepsTotal+' steps · '+m.lessons.length+' lessons'+(m.sim?' · sim':'')+'</span></div></div>'
      + (unlocked?'':'<div class="mmeta" style="margin-top:10px"><span>'+(i>0?'Finish module '+i+' to unlock':'')+'</span></div>')
      +'</div>';
    steps+='<div class="modrow"><div class="spine">'+node+'<div class="line"></div></div><div class="body">'+card+'</div></div>';
  });
  steps+='</div>';

  return header()+'<div class="view">'+crumbBar(["Role Paths",p.name])+hero
    +'<div class="sec">Modules<span class="tag">'+p.days+'-day journey</span></div>'+steps
    + (cert?'<div class="callout gold" style="margin-top:6px"><b>Path complete.</b> Your certificate is in your Profile. This content stays open as your reference library.</div>':'')
    +'</div>'+bnav();
}

function moduleScreen(){
  var p=getPath(state.pathId), m=getModule(p,state.moduleId);
  var idx=p.modules.indexOf(m);
  var lessonsHtml=m.lessons.map(function(l,i){
    var done=lessonDone(p.id,m.id,l.id);
    var ty={article:"Read",screen:"Screen walkthrough",video:"Video"}[l.type]||"Lesson";
    return '<div class="lrow" onclick="openLesson('+i+')"><div class="ck'+(done?' done':'')+'">'+(done?'✓':(i+1))+'</div>'
      +'<div class="lt"><div class="a">'+esc(l.title)+'</div><div class="b"><span class="ty">'+ty+'</span>· '+l.est+' min</div></div>'
      +'<div class="go">›</div></div>';
  }).join("");
  var allLessonsDone=m.lessons.every(function(l){return lessonDone(p.id,m.id,l.id);});
  var qp=quizPassed(p.id,m.id), qb=quizBest(p.id,m.id);
  var quizRow='<div class="lrow quizrow'+((allLessonsDone||isOwner())?'':' locked')+'" onclick="'+((allLessonsDone||isOwner())?'startQuiz()':'')+'">'
    +'<div class="ck'+(qp?' done':'')+'">'+(qp?'✓':'?')+'</div>'
    +'<div class="lt"><div class="a">Module Quiz</div><div class="b"><span class="ty">Pass 80%</span>'+(qb!=null?'· Best '+qb+'%':(allLessonsDone?'· Ready':'· Finish lessons first'))+'</div></div><div class="go">›</div></div>';
  var simRow='';
  if(m.sim){
    var sp=simPassed(p.id,m.id);
    simRow='<div class="lrow simrow'+(qp?'':' locked')+'" onclick="'+(qp?'startSim()':'')+'">'
      +'<div class="ck'+(sp?' done':'')+'">'+(sp?'✓':'▶')+'</div>'
      +'<div class="lt"><div class="a">Simulation · '+esc(m.sim.persona)+'</div><div class="b"><span class="ty">'+(m.sim.kind==='ai'?'AI Roleplay':'Guided')+'</span>'+(sp?'· Passed':(qp?'· Ready':'· Pass quiz first'))+'</div></div><div class="go">›</div></div>';
  }
  var complete=moduleComplete(p,m);
  return header()+'<div class="view">'+crumbBar([p.name,"Module "+(idx+1)])
    +'<div class="pgtitle">'+esc(m.title)+'</div><div class="pgsub">'+esc(m.objective)+'</div>'
    +'<div class="sec">Lessons<span class="tag">'+m.est+' min total</span></div><div class="llist">'+lessonsHtml+'</div>'
    +'<div class="sec">Assessment</div><div class="llist">'+quizRow+simRow+'</div>'
    + (complete?'<div class="callout gold" style="margin-top:14px"><b>Module complete ✓</b> The next module is unlocked.</div>':'')
    +'</div>'+bnav();
}

function lessonScreen(){
  var p=getPath(state.pathId), m=getModule(p,state.moduleId), l=m.lessons[state.lessonIdx];
  var done=lessonDone(p.id,m.id,l.id);
  var isLast=state.lessonIdx===m.lessons.length-1;
  var mode=state.lessonMode||"read";
  var audioSrc=l.audio||("audio/"+p.id+"."+m.id+"."+l.id+".mp3");
  var toggle='<div class="lmode">'
    +'<button class="lmbtn'+(mode==="read"?" on":"")+'" onclick="setLessonMode(\'read\')">\uD83D\uDCD6 Read</button>'
    +'<button class="lmbtn'+(mode==="listen"?" on":"")+'" onclick="setLessonMode(\'listen\')">\uD83C\uDFA7 Listen</button>'
    +'</div>';
  var player = mode==="listen"
    ? '<div class="audiowrap"><div class="acap">Press play and follow along on your screen.</div><audio controls preload="none" src="'+audioSrc+'">Your browser cannot play audio.</audio></div>'
    : '';
  return header()+'<div class="view">'+crumbBar([m.title,"Lesson "+(state.lessonIdx+1)])
    +'<div class="qprog">Lesson '+(state.lessonIdx+1)+' of '+m.lessons.length+' · '+l.est+' min</div>'
    +'<div class="pgtitle" style="margin-bottom:10px">'+esc(l.title)+'</div>'
    +toggle+player
    +'<div class="lessonbody">'+l.body+'</div>'
    +'<button class="btn '+(done?'ghost':'primary')+'" onclick="completeLesson()">'+(done? (isLast?'Done — back to module':'Next lesson ›') : (isLast?'Mark complete & finish ✓':'Mark complete & continue ›'))+'</button>'
    +'</div>'+bnav();
}

/* ---- QUIZ ---- */
function quizScreen(){
  var p=getPath(state.pathId), m=getModule(p,state.moduleId), quiz=m.quiz;
  var qi=state.quizIdx, q=quiz.questions[qi];
  var answered=state.quizAnswers[qi]!=null;
  var chosen=state.quizAnswers[qi];
  var opts=q.opts.map(function(o,i){
    var cls="opt";
    if(answered){ cls+=" disabled"; if(i===q.correct) cls+=" correct"; else if(i===chosen) cls+=" wrong"; }
    else if(chosen===i){ cls+=" sel"; }
    var ltr=String.fromCharCode(65+i);
    return '<div class="'+cls+'" onclick="'+(answered?'':'answerQuiz('+i+')')+'"><div class="lt">'+ltr+'</div><div>'+esc(o)+'</div></div>';
  }).join("");
  var pct=Math.round(qi/quiz.questions.length*100);
  var body='<div class="qprog">Question '+(qi+1)+' of '+quiz.questions.length+'</div><div class="qbar"><i style="width:'+pct+'%"></i></div>'
    +'<div class="qprompt">'+esc(q.q)+'</div>'+opts;
  if(answered){
    body+='<div class="explain"><b>'+(chosen===q.correct?'Correct. ':'Not quite. ')+'</b>'+esc(q.why)+'</div>';
    body+='<button class="btn primary" onclick="nextQuiz()">'+(qi===quiz.questions.length-1?'See result':'Next question')+'</button>';
  }
  return header()+'<div class="view">'+crumbBar([m.title,"Quiz"])+body+'</div>'+bnav();
}
function quizResultScreen(){
  var p=getPath(state.pathId), m=getModule(p,state.moduleId), quiz=m.quiz;
  var correct=0; state.quizAnswers.forEach(function(a,i){ if(a===quiz.questions[i].correct) correct++; });
  var score=Math.round(correct/quiz.questions.length*100);
  var passed=score>=80;
  var color=passed?"var(--green)":"var(--red)";
  /* persist best */
  var key=p.id+"."+m.id, prev=data.quizzes[key];
  var bestScore = prev?Math.max(prev.score,score):score;
  var everPassed = (prev&&prev.passed)||passed;
  data.quizzes[key]={score:bestScore,passed:everPassed};
  if(passed){ award("first_quiz"); if(score===100) award("perfect_quiz"); addXp(50,"Quiz passed"); }
  touchStreak(); checkModuleComplete(p.id,m.id); saveStore();
  var msg = passed ? "You passed. "+(m.sim?'The simulation is now unlocked.':'This module is complete.') : "You need 80% to pass. Review the lessons and try again — you've got this.";
  return header()+'<div class="view">'+crumbBar([m.title,"Result"])
    +'<div class="result"><div class="big">'+ring(score,120,9,color)+'<div class="pc" style="color:'+color+'">'+score+'%</div></div>'
    +'<h2>'+(passed?'Passed!':'Not yet')+'</h2><div class="msg">'+msg+'</div>'
    + (passed?'<div class="xpgain">⚡ +50 XP</div>':'')
    +'</div>'
    +'<div class="btnrow" style="margin-top:8px">'
    + (passed
        ? '<button class="btn primary" onclick="openModule(\''+m.id+'\')">Back to module</button>'
        : '<button class="btn ghost" onclick="openModule(\''+m.id+'\')">Review lessons</button><button class="btn primary" onclick="startQuiz()">Retry quiz</button>')
    +'</div></div>'+bnav();
}
function startQuiz(){ state.quizIdx=0; state.quizAnswers=[]; state.view="quiz"; render(); }
function answerQuiz(i){ state.quizAnswers[state.quizIdx]=i; render(); }
function nextQuiz(){ var m=getModule(getPath(state.pathId),state.moduleId); if(state.quizIdx<m.quiz.questions.length-1){ state.quizIdx++; render(); } else { state.view="quizresult"; render(); } }

/* ---- SIMULATION ---- */
function simScreen(){
  var p=getPath(state.pathId), m=getModule(p,state.moduleId), sim=m.sim;
  var step=sim.steps[state.simStep];
  /* build transcript from prior answers */
  var chat='<div class="chatwrap">';
  for(var i=0;i<=state.simStep;i++){
    chat+='<div class="bubble them"><div class="who">'+esc(sim.persona.replace(/^[^\sA-Za-z]+\s*/,''))+'</div>'+esc(sim.steps[i].them)+'</div>';
    if(state._simChosen && state._simChosen[i]!=null){
      chat+='<div class="bubble me"><div class="who">You</div>'+esc(sim.steps[i].choices[state._simChosen[i]].t)+'</div>';
    }
  }
  chat+='</div>';
  var body='<div class="simhdr"><div class="persona"><div class="pav">'+sim.persona.match(/^[^\sA-Za-z]+/)[0]+'</div>'
    +'<div><div class="pn">'+esc(sim.persona.replace(/^[^\sA-Za-z]+\s*/,''))+'</div><div class="pd">'+esc(sim.role)+'</div></div></div>'
    +'<div class="obj"><b>Your goal:</b> '+esc(sim.intro)+'</div></div>';
  body+=chat;
  /* if current step not yet answered, show choices */
  if(!state._simChosen || state._simChosen[state.simStep]==null){
    body+='<div class="simnote">Choose your best response</div>';
    body+=step.choices.map(function(c,i){ return '<div class="simchoice" onclick="simChoose('+i+')">'+esc(c.t)+'</div>'; }).join("");
  } else {
    var c=step.choices[state._simChosen[state.simStep]];
    body+='<div class="explain"><b>'+(c.good?'Strong move. ':'Reconsider. ')+'</b>'+esc(c.fb)+'</div>';
    var last=state.simStep===sim.steps.length-1;
    body+='<button class="btn primary" onclick="simNext()">'+(last?'See your score':'Continue')+'</button>';
  }
  return header()+'<div class="view">'+crumbBar([m.title,"Simulation"])
    +'<div class="qprog">'+(sim.kind==='ai'?'AI Roleplay':'Guided Simulation')+' · Step '+(state.simStep+1)+' of '+sim.steps.length+'</div>'
    +body+'</div>'+bnav();
}
function startSim(){ state.simStep=0; state.simScore=0; state._simChosen=[]; state.view="sim"; render(); }
function simChoose(i){ if(!state._simChosen) state._simChosen=[]; state._simChosen[state.simStep]=i; var c=getModule(getPath(state.pathId),state.moduleId).sim.steps[state.simStep].choices[i]; if(c.good) state.simScore++; render(); }
function simNext(){ var sim=getModule(getPath(state.pathId),state.moduleId).sim; if(state.simStep<sim.steps.length-1){ state.simStep++; render(); } else { state.view="simresult"; render(); } }
function simResultScreen(){
  var p=getPath(state.pathId), m=getModule(p,state.moduleId), sim=m.sim;
  var score=Math.round(state.simScore/sim.steps.length*100);
  var passed=score>=80;
  var color=passed?"var(--green)":"var(--amber)";
  if(passed && !simPassed(p.id,m.id)){ data.sims[p.id+"."+m.id]=score; award("first_sim"); addXp(80,"Simulation passed"); touchStreak(); checkModuleComplete(p.id,m.id); saveStore(); }
  var msg=passed?"Strong performance — you ran that the right way. "+(moduleComplete(p,m)?'Module complete!':''):"Close. Replay it and aim for the strongest move at each step (80% to pass).";
  return header()+'<div class="view">'+crumbBar([m.title,"Sim Result"])
    +'<div class="result"><div class="big">'+ring(score,120,9,color)+'<div class="pc" style="color:'+color+'">'+score+'%</div></div>'
    +'<h2>'+(passed?'Passed!':'Almost')+'</h2><div class="msg">'+msg+'</div>'
    +(passed?'<div class="xpgain">⚡ +80 XP</div>':'')+'</div>'
    +'<div class="btnrow" style="margin-top:8px">'
    +(passed?'<button class="btn primary" onclick="openModule(\''+m.id+'\')">Back to module</button>'
      :'<button class="btn primary" onclick="startSim()">Replay simulation</button>')
    +'</div></div>'+bnav();
}

/* ---- MY PATH (router helper) ---- */
function mypathScreen(){
  /* show the most-progressed in-progress path, else home grid */
  var inProg=CURRICULUM.filter(function(p){var x=pathProgressPct(p);return x>0&&x<100;});
  if(inProg.length){ inProg.sort(function(a,b){return pathProgressPct(b)-pathProgressPct(a);}); state.pathId=inProg[0].id; return pathScreen(); }
  if(state.pathId){ return pathScreen(); }
  /* none started — gentle prompt */
  return header()+'<div class="view"><div class="pgtitle">My Path</div>'
    +'<div class="pgsub">You haven\'t started a path yet. As the admin/demo account you can preview any of the six role paths — pick one from the home screen to begin.</div>'
    +'<button class="btn primary" onclick="go(\'home\')">Choose a role path</button>'
    +'<div class="callout" style="margin-top:18px"><b>How it works:</b> each path unlocks module by module. Finish a module\'s lessons, pass its quiz (80%) and clear any simulation to unlock the next.</div>'
    +'</div>'+bnav();
}

/* ---- REFERENCE LIBRARY ---- */
function referenceScreen(){
  var cats=["all"].concat(REFERENCE.map(function(r){return r.cat;}).filter(function(v,i,a){return a.indexOf(v)===i;}));
  var chips=cats.map(function(c){return '<div class="fchip'+(state.refFilter===c?' on':'')+'" onclick="setRefFilter(\''+c+'\')">'+(c==="all"?"All topics":c)+'</div>';}).join("");
  var q=(state.refQuery||"").toLowerCase();
  var results=REFERENCE.filter(function(r){
    var inCat = state.refFilter==="all"||r.cat===state.refFilter;
    var inQ = !q || (r.title+" "+r.cat+" "+r.body).toLowerCase().indexOf(q)>=0;
    return inCat&&inQ;
  });
  var cards = results.length ? results.map(function(r){
    return '<div class="refcard" onclick="openRef(\''+r.id+'\')"><div class="ic">'+r.icon+'</div>'
      +'<div><div class="t">'+esc(r.title)+'</div><div class="d">'+esc(r.cat)+' · quick how-to</div><div class="m">Updated '+r.updated+'</div></div><div class="go">›</div></div>';
  }).join("") : '<div class="empty">No articles match "'+esc(state.refQuery)+'".<br>Try a different search or clear the filter.</div>';
  return header()+'<div class="view"><div class="pgtitle">Reference Library</div>'
    +'<div class="pgsub">Your "how do I do X again?" shelf. Searchable, screenshot-led, always open.</div>'
    +'<div class="searchbar"><span class="ic">🔍</span><input id="refq" placeholder="Search — e.g. reschedule, GP, options…" value="'+esc(state.refQuery)+'" oninput="onRefQuery(this.value)"></div>'
    +'<div class="chips-scroll">'+chips+'</div>'
    +cards+'</div>'+bnav();
}
function refarticleScreen(){
  var r=REFERENCE.find(function(x){return x.id===state.refId;});
  if(!r) return referenceScreen();
  return header()+'<div class="view">'+crumbBar(["Library",r.cat])
    +'<div class="pgtitle" style="margin-bottom:6px">'+esc(r.title)+'</div>'
    +'<div class="qprog">Updated '+r.updated+' · '+esc(r.cat)+'</div>'
    +'<div class="lessonbody" style="margin-top:12px">'+r.body+'</div>'
    +'<button class="btn ghost" onclick="go(\'reference\')">Back to library</button>'
    +'</div>'+bnav();
}

/* ---- PROFILE ---- */
function profileScreen(){
  var lvl=levelFromXp(data.xp), xpInLvl=(data.xp||0)%300, pct=Math.round(xpInLvl/300*100);
  var certs=CURRICULUM.filter(function(p){return canAccess(p.id);}).map(function(p){
    var cert=data.certs[p.id], prog=pathProgressPct(p);
    var stat = cert?['cert','Certified '+cert]:prog>0?['prog',prog+'% complete']:['lock','Not started'];
    return '<div class="certcard"><div class="seal">'+(cert?'🏆':prog>0?'📘':'🔒')+'</div>'
      +'<div class="cn">'+esc(p.name)+'</div><div class="cd">'+esc(p.summary)+'</div>'
      +'<span class="cstat '+stat[0]+'">'+stat[1]+'</span>'
      +(cert?' <button class="sbtn" style="margin-left:8px" onclick="printCert(\''+p.id+'\')">View certificate</button>':'')
      +'</div>';
  }).join("");
  var badges=BADGES.map(function(b){
    var earned=data.badges.indexOf(b.id)>=0;
    return '<div class="bcard'+(earned?'':' locked')+'"><div class="be">'+b.emoji+'</div><div class="bn">'+esc(b.name)+'</div><div class="bd">'+esc(b.desc)+'</div></div>';
  }).join("");
  return header()+'<div class="view">'
    +'<div class="pathhero"><div class="ring">'+ring(pct,78,7,"var(--gold)")+'<div class="num" style="color:var(--gold)">L'+lvl+'</div></div>'
    +'<div class="meta"><div class="nm">'+esc((currentAccount()||{}).name||"User")+'</div><div class="dt">Signed in · role-based access</div>'
    +'<div class="chips"><span class="chip gold">'+(data.xp||0)+' XP</span><span class="chip cyan">'+(data.streak||0)+'-day streak</span><span class="chip green">'+Object.keys(data.certs).length+' certs</span></div></div></div>'
    +'<div class="sec">Certifications</div>'+certs
    +'<div class="sec">Badges<span class="tag">'+data.badges.length+' / '+BADGES.length+'</span></div><div class="badgegrid">'+badges+'</div>'
    +'<div class="sec">Account</div><button class="btn ghost" onclick="logout()">Sign out</button><button class="btn ghost" onclick="resetProgress()" style="margin-top:10px">Reset all progress</button>'
    +'<div class="note">Progress is stored locally on this device. In the production build this lives in Supabase with Google Workspace SSO and per-role visibility.</div>'
    +'</div>'+bnav();
}

/* ---- ADMIN ---- */
function adminScreen(){
  /* demo roster mapped to paths */
  var roster=[
    {n:"SCR / DSR — Seat 1",r:"scr"},{n:"SCR / DSR — Seat 2",r:"scr"},{n:"SCR / DSR — Seat 3",r:"scr"},
    {n:"Owner — Seat 1",r:"owner"},{n:"Office Manager — Seat 1",r:"owner"},
    {n:"Service / Install — Team",r:"tech"},{n:"Sales Tech — Seat 1",r:"sales"},
    {n:"Manager — Seat 1",r:"manager"},{n:"Support Office — Seat 1",r:"support"},
  ];
  var rows=roster.map(function(u){
    var p=getPath(u.r);
    /* admin's own progress is the only real data; others shown as illustrative 0 unless admin = this device */
    var pct = pathProgressPct(p); // device-level demo
    return '<div class="arow"><span class="anm">'+esc(u.n)+'</span><span class="arole">'+esc(p.name.split(" / ")[0])+'</span>'
      +'<span class="apb"><i style="width:'+pct+'%"></i></span><span class="apc">'+pct+'%</span></div>';
  }).join("");
  var pathStats=CURRICULUM.map(function(p){
    var pct=pathProgressPct(p);
    return '<div class="arow"><span class="anm">'+esc(p.name)+'</span><span class="apb"><i style="width:'+pct+'%"></i></span><span class="apc">'+pct+'%</span></div>';
  }).join("");
  return header()+'<div class="view"><div class="pgtitle">Admin Console</div>'
    +'<div class="pgsub">Invite users, assign roles, grant cross-role modules and track completion. (Prototype view — completion reflects this device.)</div>'
    +'<div class="sec">Completion by Path</div><div class="atable">'+pathStats+'</div>'
    +'<div class="sec">Team Roster</div><div class="atable">'+rows+'</div>'
    +'<div class="btnrow" style="margin-top:18px"><button class="btn ghost" onclick="toast(\'➕\',\'Invite flow — wired to Supabase in production\')">Invite user</button><button class="btn ghost" onclick="toast(\'📤\',\'Compliance export — production feature\')">Export report</button></div>'
    +'<div class="note">In production: add/invite users, assign a primary role path, grant cross-role modules, view completion by person and role, and export a compliance report — all enforced by row-level security in Supabase.</div>'
    +'</div>'+bnav();
}

/* ===================== USER MANAGEMENT (admin only) ===================== */
var UM_USERS=[], UM_PROG={};
function _ld(d,pid,mid,lid){ return !!(d&&d.progress&&d.progress[pid+"."+mid+"."+lid]); }
function _qz(d,pid,mid){ var r=d&&d.quizzes&&d.quizzes[pid+"."+mid]; return !!(r&&r.passed); }
function _sm(d,pid,mid){ return !!(d&&d.sims&&d.sims[pid+"."+mid]); }
function _mc(d,p,m){ return m.lessons.every(function(l){return _ld(d,p.id,m.id,l.id);}) && _qz(d,p.id,m.id) && (m.sim?_sm(d,p.id,m.id):true); }
function umStats(d,ids){ d=d||{}; var asg=0,comp=0,cur=null; (ids||[]).forEach(function(id){ var p=getPath(id); if(!p) return; p.modules.forEach(function(m){ asg++; if(_mc(d,p,m)) comp++; else if(!cur) cur=(p.name.split(" / ")[0])+" — "+m.title; }); }); return {asg:asg,comp:comp,pct:asg?Math.round(comp/asg*100):0,cur:cur||"—"}; }
function umFmtMins(sec){ sec=sec||0; var h=Math.floor(sec/3600),m=Math.floor((sec%3600)/60); return h?(h+"h "+m+"m"):(m+"m"); }
function umExportCsv(){
  var rows=[["Name","Email","Status","Access","Last login","Modules assigned","Modules completed","Completion %","Current module","Time on platform"]];
  UM_USERS.forEach(function(u){ var pr=UM_PROG[u.id]||{}; var st=umStats(pr.data,u.titan_access); rows.push([u.name||"",u.email||"",u.status||"",(u.titan_access||[]).map(umRoleName).join("; "),u.last_login?new Date(u.last_login).toLocaleString():"",st.asg,st.comp,st.pct,st.cur,umFmtMins(pr.time)]); });
  var csv=rows.map(function(r){ return r.map(function(x){ x=String(x==null?"":x); return /[",\n]/.test(x)?'"'+x.replace(/"/g,'""')+'"':x; }).join(","); }).join("\n");
  try{ var blob=new Blob([csv],{type:"text/csv;charset=utf-8"}); var url=URL.createObjectURL(blob); var a=document.createElement("a"); a.href=url; a.download="titan-users-report.csv"; document.body.appendChild(a); a.click(); document.body.removeChild(a); setTimeout(function(){URL.revokeObjectURL(url);},1000); if(typeof toast==="function") toast("\uD83D\uDCC4","Report exported"); }catch(e){ if(typeof toast==="function") toast("\u26A0\uFE0F","Export failed"); }
}
function usersScreen(){
  setTimeout(loadUsersAdmin,0);
  return header()+'<div class="view"><div class="pgtitle">User Management</div>'
    +'<div class="pgsub">Approve sign-ups, assign each person their course access, and monitor the team. Admins only.</div>'
    +'<style>'
    +'.umbar{font-size:12px;color:var(--muted-2);margin:4px 0 12px}'
    +'.umcard{border:1px solid var(--line);border-radius:14px;padding:14px 16px;margin-bottom:12px;background:rgba(255,255,255,.02)}'
    +'.umcard.off{opacity:.55}'
    +'.umhd{display:flex;justify-content:space-between;align-items:flex-start;gap:12px;flex-wrap:wrap}'
    +'.umnm{font-weight:700;font-size:15px}'
    +'.umem{font-size:12px;color:var(--muted-2);margin-top:2px}'
    +'.umreq,.ummeta{font-size:11px;color:var(--muted-2);text-align:right}'
    +'.umbadge{font-size:9px;font-weight:800;letter-spacing:.6px;text-transform:uppercase;padding:2px 7px;border-radius:999px;margin-left:8px}'
    +'.umbadge.approved{background:rgba(41,170,225,.18);color:var(--cyan-2)}'
    +'.umbadge.pending{background:rgba(212,169,74,.22);color:var(--gold)}'
    +'.umbadge.disabled{background:rgba(150,150,150,.2);color:var(--muted-2)}'
    +'.umlbl{font-size:11px;color:var(--muted-2);margin:12px 0 7px;text-transform:uppercase;letter-spacing:.6px}'
    +'.umchecks{display:grid;grid-template-columns:1fr 1fr;gap:7px 16px}'
    +'.umck{display:flex;align-items:center;gap:7px;font-size:13px;cursor:pointer}'
    +'.umck input{accent-color:var(--cyan-2)}'
    +'.umaccess{margin-top:10px;display:flex;flex-wrap:wrap;gap:6px}'
    +'.umchip{font-size:11px;padding:3px 9px;border-radius:999px;border:1px solid var(--line);color:var(--text)}'
    +'.umstats{display:flex;flex-wrap:wrap;gap:6px 16px;margin-top:10px;font-size:11px;color:var(--muted-2)}'
    +'.umstats b{color:var(--cyan-2);font-size:13px}'
    +'.umq{font-size:11px;color:var(--muted-2);font-style:italic}'
    +'</style>'
    +'<div id="umroot" style="margin-top:4px">Loading users…</div>'
    +'</div>'+bnav();
}
function loadUsersAdmin(){
  var root=$("umroot"); if(!root) return;
  if(!isAdmin()){ root.innerHTML='<div class="note">Admins only.</div>'; return; }
  if(!sb){ root.innerHTML='<div class="note">Connection unavailable — refresh.</div>'; return; }
  root.innerHTML='Loading users…';
  sb.from("users").select("id,name,email,status,role,titan_access,titan_requested_role,last_login").eq("app","titan").then(function(res){
    if(res.error){ root.innerHTML='<div class="note">Couldn\'t load users: '+esc(res.error.message||"error")+'</div>'; return; }
    var rank={pending:0,approved:1,disabled:2};
    UM_USERS=(res.data||[]).slice().sort(function(a,b){
      var d=(rank[a.status]==null?9:rank[a.status])-(rank[b.status]==null?9:rank[b.status]); if(d) return d;
      return String(a.name||a.email).localeCompare(String(b.name||b.email));
    });
    sb.from("titan_progress").select("user_id,progress,time_spent_seconds").then(function(pres){
      UM_PROG={}; ((pres&&pres.data)||[]).forEach(function(r){ UM_PROG[r.user_id]={data:(r.progress||{}),time:(r.time_spent_seconds||0)}; });
      renderUsersTable();
    }, function(){ UM_PROG={}; renderUsersTable(); });
  }, function(){ root.innerHTML='<div class="note">Couldn\'t load users — try again.</div>'; });
}
function umRoleName(rid){ var p=getPath(rid); return p?p.name:rid; }
function umAccessChips(arr){ if(!arr||!arr.length) return '<span class="umq">No access yet</span>'; return arr.map(function(id){ return '<span class="umchip">'+esc(umRoleName(id))+'</span>'; }).join(""); }
function umAccessChecks(id,current){ current=current||[]; return CURRICULUM.map(function(p){ var on=current.indexOf(p.id)>=0?" checked":""; return '<label class="umck"><input type="checkbox" id="acc_'+id+'_'+p.id+'"'+on+'> '+esc(p.name)+'</label>'; }).join(""); }
function umCollectAccess(id){ var out=[]; CURRICULUM.forEach(function(p){ var c=$("acc_"+id+"_"+p.id); if(c&&c.checked) out.push(p.id); }); return out; }
function umFmtDate(s){ if(!s) return "—"; try{ var d=new Date(s); return d.toLocaleDateString()+" "+d.toLocaleTimeString([],{hour:"2-digit",minute:"2-digit"}); }catch(e){ return "—"; } }
function defaultAccessFor(rid){ var m={owner:["owner","manager","accounts","scr","support","tech","sales","marketing"],managers:["owner","manager","accounts","scr","support","tech","sales","marketing"],accounts:["accounts"],scrdsr:["scr","support"],supportoffice:["scr","support"],installtech:["tech","sales"],servicetech:["tech","sales"],marketingpro:["scr","marketing"]}; return m[rid]||[]; }
function renderUsersTable(){
  var root=$("umroot"); if(!root) return;
  var pend=UM_USERS.filter(function(u){return u.status==="pending";});
  var rest=UM_USERS.filter(function(u){return u.status!=="pending";});
  var c=UM_USERS.reduce(function(a,u){a[u.status]=(a[u.status]||0)+1;return a;},{});
  var html='<div class="umbar">'+(c.pending||0)+' pending · '+(c.approved||0)+' active · '+(c.disabled||0)+' disabled</div>';
  if(UM_USERS.length) html+='<div class="btnrow" style="margin:0 0 10px"><button class="btn ghost" onclick="umExportCsv()">Export CSV report</button></div>';
  if(pend.length){
    html+='<div class="sec">Pending approval ('+pend.length+')</div>';
    pend.forEach(function(u){
      var pre=(u.titan_access&&u.titan_access.length)?u.titan_access:(u.titan_requested_role?defaultAccessFor(u.titan_requested_role):[]);
      html+='<div class="umcard"><div class="umhd"><div><div class="umnm">'+esc(u.name||u.email)+'</div><div class="umem">'+esc(u.email)+'</div></div>'
        +'<div class="umreq">Requested:<br>'+esc(u.titan_requested_role?umRoleName(u.titan_requested_role):"—")+'</div></div>'
        +'<div class="umlbl">Grant access to these paths</div><div class="umchecks">'+umAccessChecks(u.id,pre)+'</div>'
        +'<div class="btnrow" style="margin-top:12px"><button class="btn" onclick="umApprove(\''+u.id+'\')">Approve</button> <button class="btn ghost" onclick="umSetStatus(\''+u.id+'\',\'disabled\')">Reject</button></div></div>';
    });
  }
  html+='<div class="sec">Team ('+rest.length+')</div>';
  if(!rest.length){ html+='<div class="note">No active users yet.</div>'; }
  rest.forEach(function(u){
    var off=u.status==="disabled"; var pr=UM_PROG[u.id]||{}; var st=umStats(pr.data,u.titan_access);
    html+='<div class="umcard'+(off?" off":"")+'"><div class="umhd"><div><div class="umnm">'+esc(u.name||u.email)+'<span class="umbadge '+u.status+'">'+u.status+'</span></div><div class="umem">'+esc(u.email)+'</div></div>'
      +'<div class="ummeta">Last login<br>'+umFmtDate(u.last_login)+'</div></div>'
      +'<div class="umstats"><span><b>'+st.pct+'%</b> complete</span><span>'+st.comp+'/'+st.asg+' modules</span><span>Current: '+esc(st.cur)+'</span><span>'+umFmtMins(pr.time)+' on platform</span></div>'
      +'<div class="umaccess" id="umacc_'+u.id+'">'+umAccessChips(u.titan_access)+'</div>'
      +'<div id="umedit_'+u.id+'" style="display:none;margin-top:10px"><div class="umchecks">'+umAccessChecks(u.id,u.titan_access)+'</div>'
        +'<div class="btnrow" style="margin-top:8px"><button class="btn" onclick="umSaveAccess(\''+u.id+'\')">Save access</button> <button class="btn ghost" onclick="umToggleEdit(\''+u.id+'\',false)">Cancel</button></div></div>'
      +'<div class="btnrow" id="umbtns_'+u.id+'" style="margin-top:10px"><button class="btn ghost" onclick="umToggleEdit(\''+u.id+'\',true)">Edit access</button> '
        +(off?'<button class="btn ghost" onclick="umSetStatus(\''+u.id+'\',\'approved\')">Re-enable</button>':'<button class="btn ghost" onclick="umSetStatus(\''+u.id+'\',\'disabled\')">Disable</button>')+'</div></div>';
  });
  html+='<div class="note">Completion updates live as people work through the platform. Time-on-platform accrues while the app is open.</div>';
  root.innerHTML=html;
}
function umToggleEdit(id,on){ var e=$("umedit_"+id),a=$("umacc_"+id),b=$("umbtns_"+id); if(e)e.style.display=on?"":"none"; if(a)a.style.display=on?"none":""; if(b)b.style.display=on?"none":""; }
function umApprove(id){ var acc=umCollectAccess(id); sb.from("users").update({status:"approved",titan_access:acc}).eq("id",id).eq("app","titan").then(function(r){ if(r.error){ toast("\u26A0\uFE0F",r.error.message||"Update failed"); return; } toast("\u2713","Approved"); loadUsersAdmin(); }); }
function umSaveAccess(id){ var acc=umCollectAccess(id); sb.from("users").update({titan_access:acc}).eq("id",id).eq("app","titan").then(function(r){ if(r.error){ toast("\u26A0\uFE0F",r.error.message||"Update failed"); return; } toast("\u2713","Access updated"); loadUsersAdmin(); }); }
function umSetStatus(id,st){ sb.from("users").update({status:st}).eq("id",id).eq("app","titan").then(function(r){ if(r.error){ toast("\u26A0\uFE0F",r.error.message||"Update failed"); return; } toast("\u2713",st==="approved"?"Re-enabled":(st==="disabled"?"Disabled":st)); loadUsersAdmin(); }); }

/* ---- certificate (print view) ---- */
function printCert(pid){
  var p=getPath(pid); var d=data.certs[pid]||new Date().toISOString().slice(0,10);
  var w=window.open("","_blank");
  if(!w){ toast("⚠️","Allow pop-ups to view the certificate"); return; }
  w.document.write('<!doctype html><html><head><title>Certificate — '+esc(p.name)+'</title>'
   +'<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;700;800&display=swap" rel="stylesheet">'
   +'<style>body{margin:0;font-family:Inter,sans-serif;background:#0B2545;display:flex;align-items:center;justify-content:center;min-height:100vh;padding:30px}'
   +'.c{background:#fff;color:#0B2545;width:760px;max-width:100%;padding:60px;border:2px solid #B68B4C;border-radius:8px;text-align:center;box-shadow:0 20px 80px rgba(0,0,0,.4)}'
   +'.k{font-size:11px;letter-spacing:6px;color:#1A7A8C;font-weight:700;text-transform:uppercase}'
   +'h1{font-size:40px;margin:18px 0 6px;letter-spacing:1px}.s{font-size:14px;color:#4a5d73;margin-bottom:34px}'
   +'.nm{font-size:30px;font-weight:800;color:#B68B4C;border-bottom:2px solid #eee;display:inline-block;padding:0 30px 8px;margin-bottom:10px}'
   +'.r{font-size:18px;font-weight:600;margin:18px 0 4px}.dt{font-size:12px;color:#4a5d73;letter-spacing:1px}'
   +'.ft{margin-top:40px;display:flex;justify-content:space-between;font-size:11px;color:#4a5d73}'
   +'.seal{font-size:46px;margin-bottom:10px}@media print{body{background:#fff}.c{box-shadow:none}}</style></head><body>'
   +'<div class="c"><div class="seal">🏆</div><div class="k">Titan Academy</div>'
   +'<h1>Certificate of Completion</h1><div class="s">This certifies that</div>'
   +'<div class="nm">'+esc((currentAccount()||{}).name||"User")+'</div>'
   +'<div class="r">has achieved ServiceTitan certification in</div>'
   +'<div class="r" style="color:#1A7A8C">'+esc(p.name)+'</div>'
   +'<div class="dt">Issued '+esc(d)+' · '+p.modules.length+' modules · the right way</div>'
   +'<div class="ft"><span>Program Director</span><span>ST-Certified ✓</span></div></div>'
   +'<script>setTimeout(function(){window.print&&window.print()},500)<\/script></body></html>');
  w.document.close();
}

