var SCREENS={ home:homeScreen, path:pathScreen, module:moduleScreen, lesson:lessonScreen,
  quiz:quizScreen, quizresult:quizResultScreen, sim:simScreen, simresult:simResultScreen,
  reference:referenceScreen, refarticle:refarticleScreen, profile:profileScreen, admin:adminScreen, users:usersScreen, mypath:mypathScreen };

var navStack=["home"];
function go(v){ if(v!==state.view) navStack.push(v); state.view=v; window.scrollTo(0,0); render(); }
function goBack(){ navStack.pop(); var prev=navStack[navStack.length-1]||"home"; state.view=prev; window.scrollTo(0,0); render(); }
function navTo(v){ navStack=["home"]; if(v!=="home") navStack.push(v); state.view=v; window.scrollTo(0,0); render(); }

function openPath(id){ if(!ADVANCED_PATHS[id] && !canAccess(id)){ lockedTile(); return; } state.pathId=id; go("path"); }
function lockedTile(){ toast("🔒","Locked — not part of your role"); }
function openModule(id){ state.moduleId=id; go("module"); }
function setLessonMode(mode){ state.lessonMode=mode; render(); }
function openLesson(i){ state.lessonIdx=i; state.lessonMode="read"; go("lesson"); }
function lockMsg(i){ toast("🔒","Finish module "+i+" to unlock this one."); }
function completeLesson(){
  var p=getPath(state.pathId), m=getModule(p,state.moduleId), l=m.lessons[state.lessonIdx];
  markLesson(p.id,m.id,l.id);
  if(state.lessonIdx<m.lessons.length-1){ state.lessonIdx++; window.scrollTo(0,0); render(); }
  else { openModule(m.id); }
}
function openRef(id){ state.refId=id; if(data.refOpened.indexOf(id)<0){ data.refOpened.push(id); if(data.refOpened.length>=5) award("explorer"); saveStore(); } go("refarticle"); }
function setRefFilter(c){ state.refFilter=c; render(); }
function onRefQuery(v){ state.refQuery=v; var el=document.activeElement; render(); var q=$("refq"); if(q){ q.focus(); q.setSelectionRange(q.value.length,q.value.length); } }
function resetProgress(){ if(confirm("Reset all progress, XP, badges and certificates on this device?")){ data=Object.assign({},DEFAULT_STATE,{progress:{},quizzes:{},sims:{},badges:[],refOpened:[],certs:{}}); saveStore(); state.pathId=null; navTo("home"); toast("↺","Progress reset"); } }

function toggleTheme(){ var b=document.body; var t=b.getAttribute("data-theme")==="dark"?"light":"dark"; b.setAttribute("data-theme",t); try{localStorage.setItem("titan_theme",t);}catch(e){} }

function render(){ $("app").innerHTML=(SCREENS[state.view]||homeScreen)(); if(state.view==="home" && typeof animateHome==="function") requestAnimationFrame(animateHome); }

