function normKey(u){ return String(u||"").toLowerCase().replace(/[^a-z]/g,""); }
function currentAccount(){ return ACCOUNT; }
function isOwner(){ return !!(ACCOUNT&&ACCOUNT.admin); }
function isAdmin(){ return !!(ACCOUNT&&ACCOUNT.admin); }
function accessibleIds(){ var a=ACCOUNT; if(!a) return []; return a.access==="all"?CURRICULUM.map(function(p){return p.id;}):(a.access||[]); }
function canAccess(pid){ return accessibleIds().indexOf(pid)>=0; }

/* gate: sign-in vs create-account modes */
function applyGateMode(){
  ["gname","gemail","gp","gu","gbtn"].forEach(function(id){ var el=$(id); if(el && (id==="gname"||id==="gu")) el.style.display = SIGNUP_MODE?"":"none"; });
  var pw=$("gp"); if(pw) pw.setAttribute("autocomplete", SIGNUP_MODE?"new-password":"current-password");
  var btn=$("gbtn"); if(btn) btn.textContent = SIGNUP_MODE ? "Create account" : "Sign in";
  var hint=$("ghint"); if(hint) hint.innerHTML = (SIGNUP_MODE
    ? 'Have an account? <a href="#" onclick="toggleSignup();return false" style="color:var(--cyan-2);text-decoration:underline">Sign in</a>'
    : 'New to Titan Academy? <a href="#" onclick="toggleSignup();return false" style="color:var(--cyan-2);text-decoration:underline">Create an account</a>');
  gateErr("");
}
function toggleSignup(){ SIGNUP_MODE=!SIGNUP_MODE; applyGateMode(); }
function gateSubmit(){ if(SIGNUP_MODE) doSignup(); else tryLogin(); }
function gateErr(msg){ var er=$("gerr"); if(er){ er.style.color=""; er.style.fontSize=""; er.textContent=msg||""; } }

function googleSignin(){
  if(!sb){ gateErr("Connection unavailable — refresh and try again"); return; }
  gateErr("Redirecting to Google\u2026");
  sb.auth.signInWithOAuth({ provider:"google", options:{ redirectTo:location.origin, queryParams:{ hd:"proximityplumbing.com.au", prompt:"select_account" } } })
    .then(function(res){ if(res && res.error) gateErr(res.error.message||"Google sign-in isn't enabled yet"); })
    .catch(function(){ gateErr("Google sign-in isn't enabled yet"); });
}

function tryLogin(){
  var email=(($("gemail")||{}).value||"").trim().toLowerCase(), p=($("gp")||{}).value||"";
  if(!sb){ gateErr("Connection unavailable — refresh and try again"); return; }
  if(!email||!p){ gateErr("Enter your email and password"); return; }
  gateErr("Signing in…");
  sb.auth.signInWithPassword({email:email, password:p}).then(function(res){
    if(res.error){ gateErr(res.error.message||"Incorrect email or password"); return; }
    loadProfileAndEnter();
  }).catch(function(){ gateErr("Sign-in failed — try again"); });
}

function doSignup(){
  var name=(($("gname")||{}).value||"").trim();
  var email=(($("gemail")||{}).value||"").trim().toLowerCase();
  var p=($("gp")||{}).value||"";
  var role=(($("gu")||{}).value||"");
  if(!sb){ gateErr("Connection unavailable — refresh and try again"); return; }
  if(!name){ gateErr("Enter your full name"); return; }
  if(!email||!p){ gateErr("Enter your email and a password"); return; }
  if(p.length<6){ gateErr("Password must be at least 6 characters"); return; }
  if(!role){ gateErr("Choose your role"); return; }
  gateErr("Creating your account…");
  sb.auth.signUp({email:email, password:p, options:{data:{full_name:name, requested_role:role}}}).then(function(res){
    if(res.error){ gateErr(res.error.message||"Could not create account"); return; }
    function finish(){ SIGNUP_MODE=false; applyGateMode(); if(typeof toast==="function") toast("\u2713","Account created — an admin will approve you, then you can sign in."); gateErr(""); }
    if(res.data && res.data.session){
      sb.rpc("titan_register",{p_name:name, p_requested_role:role}).then(function(){ sb.auth.signOut().then(finish, finish); }, function(){ sb.auth.signOut().then(finish, finish); });
    } else { finish(); }
  }).catch(function(){ gateErr("Could not create account — try again"); });
}

function loadProfileAndEnter(){
  if(!sb){ gateErr("Connection unavailable"); return; }
  sb.auth.getUser().then(function(gu){
    var u=gu&&gu.data?gu.data.user:null;
    if(!u){ gateErr("Session error — sign in again"); return; }
    var email=(u.email||"").toLowerCase();
    sb.rpc("is_titan_admin").then(function(af){
      var admin=!!(af&&af.data===true);
      if(admin){ ACCOUNT={ name:u.email, access:"all", admin:true, home:null }; PROFILE=null; afterAuth(u.id); return; }
      sb.from("users").select("name,role,status,titan_access").eq("app","titan").eq("email",email).maybeSingle().then(function(pr){
        var row=(pr&&pr.data)?pr.data:null;
        if(!row){
          var md=u.user_metadata||{};
          sb.rpc("titan_register",{p_name:md.full_name||"", p_requested_role:md.requested_role||""}).then(function(){ showGateMessage("Your account is awaiting admin approval."); }, function(){ showGateMessage("Your account is awaiting admin approval."); });
          return;
        }
        if(row.status==="pending"){ showGateMessage("Your account is awaiting admin approval."); return; }
        if(row.status==="disabled"){ showGateMessage("This account has been disabled. Contact an admin."); return; }
        ACCOUNT={ name:row.name, access:(row.role==="admin"?"all":(row.titan_access||[])), admin:false, home:((row.titan_access&&row.titan_access[0])||null) }; PROFILE=row; afterAuth(u.id);
      });
    }, function(){ gateErr("Could not verify access — try again"); });
  });
}

var _hbTimer=null;
function afterAuth(uid){
  TP_UID=uid;
  if(!sb){ enterApp(); return; }
  sb.from("titan_progress").select("progress").eq("user_id",uid).maybeSingle().then(function(pr){
    var cloud=(pr&&pr.data&&pr.data.progress)?pr.data.progress:null;
    if(cloud && typeof cloud==="object"){ data=Object.assign({},DEFAULT_STATE,cloud); try{ localStorage.setItem(STORE_KEY,JSON.stringify(data)); }catch(e){} }
    startHeartbeat(); enterApp();
  }, function(){ startHeartbeat(); enterApp(); });
}
function startHeartbeat(){
  if(sb){ try{ sb.rpc("titan_heartbeat",{p_seconds:0}).then(function(){},function(){}); }catch(e){} }
  if(_hbTimer) clearInterval(_hbTimer);
  _hbTimer=setInterval(function(){ if(sb&&TP_UID&&!document.hidden){ try{ sb.rpc("titan_heartbeat",{p_seconds:60}).then(function(){},function(){}); }catch(e){} } }, 60000);
}
function enterApp(){ showApp(); }
function showApp(){ var g=$("gate"); if(g) g.style.display="none"; var a=$("app"); if(a) a.style.display=""; touchStreak(); render(); }

function showGateMessage(msg){
  ["gname","gemail","gp","gu","gbtn"].forEach(function(id){ var el=$(id); if(el) el.style.display="none"; });
  var er=$("gerr"); if(er){ er.style.color="var(--text)"; er.style.fontSize="13px"; er.textContent=msg; }
  var hint=$("ghint"); if(hint){ hint.innerHTML='<a href="#" onclick="logout();return false" style="color:var(--cyan-2);text-decoration:underline">Sign out</a>'; }
}

function logout(){ try{ if(sb){ sb.auth.signOut().then(function(){location.reload();}, function(){location.reload();}); } else { location.reload(); } }catch(e){ location.reload(); } }

/* session bar */
function mountSessionBar(){
  if(document.getElementById("sessbar")) return;
  var bar=document.createElement("div"); bar.className="sessionbar"; bar.id="sessbar";
  var _a=currentAccount(); var _who=_a?_a.name:"User";
  bar.innerHTML='<div class="who"><span class="dot"></span>'+esc(_who)+'</div><button class="sbtn" onclick="logout()">Sign out</button>';
  document.body.appendChild(bar);
}

/* boot */
(function(){
  try{ var t=localStorage.getItem("titan_theme"); if(t) document.body.setAttribute("data-theme",t); }catch(e){}
  applyGateMode();
  if(sb){ sb.auth.getSession().then(function(s){ if(s&&s.data&&s.data.session) loadProfileAndEnter(); }).catch(function(){}); }
})();

/* ===== NATIVE-FEEL LAYER — JS utilities (additive, dependency-free) ===== */
function haptic(ms){ if(navigator.vibrate) navigator.vibrate(ms||10); }
document.addEventListener('click', function(e){ if(e.target.closest('button,.tap,.rolecard')) haptic(8); });
var NFStore={
  get:function(k,f){ try{ var v=localStorage.getItem(k); return v==null?(f==null?null:f):JSON.parse(v);}catch(e){return f==null?null:f;} },
  set:function(k,v){ try{ localStorage.setItem(k,JSON.stringify(v)); }catch(e){} },
  remove:function(k){ try{ localStorage.removeItem(k); }catch(e){} }
};
function trackScroll(el,key){ if(!el) return; el.scrollTop=NFStore.get('scroll_'+key,0); var t;
  el.addEventListener('scroll',function(){ clearTimeout(t); t=setTimeout(function(){ NFStore.set('scroll_'+key,el.scrollTop); },150); }); }
if('serviceWorker' in navigator){ window.addEventListener('load',function(){ var hadController=!!navigator.serviceWorker.controller; navigator.serviceWorker.register('/sw.js').then(function(reg){ try{reg.update();}catch(e){} setInterval(function(){ try{reg.update();}catch(e){} }, 3600000); }).catch(function(){}); var refreshing=false; navigator.serviceWorker.addEventListener('controllerchange',function(){ if(refreshing||!hadController) return; refreshing=true; location.reload(); }); }); }
var deferredPrompt=null;
window.addEventListener('beforeinstallprompt',function(e){ e.preventDefault(); deferredPrompt=e; });
/* ===== END NATIVE-FEEL LAYER JS ===== */
